from .common import *
from .lg import S


def R(src, snk, bend=0.45):
    return A(src, snk, bend, rad=True)


def theory(B):
    B.h2("10.7  Electronic structure in depth: why CH<sub>2</sub> is a triplet and CF<sub>2</sub> a singlet")
    B.p("The valence orbitals of a bent carbene are a σ orbital (an sp<sup>2</sup>-like hybrid on carbon, holding the non-bonding pair in the singlet) and a nearly pure p orbital perpendicular to the molecular plane. "
        "The two non-bonding electrons can occupy them in two ways: <b>singlet</b> (σ<sup>2</sup> p<sup>0</sup>, spins paired, ¹A<sub>1</sub>) or <b>triplet</b> (σ<sup>1</sup> p<sup>1</sup>, spins parallel, ³B<sub>1</sub>). The singlet–triplet energy gap ΔE<sub>ST</sub> = E(singlet) − E(triplet) decides the chemistry.")
    B.table(["Carbene", "Ground state", "ΔE<sub>ST</sub> (kcal mol<sup>−1</sup>, recalled)", "H–C–H / X–C–X angle", "Remark"],
        [[":CH<sub>2</sub>", "triplet (³B<sub>1</sub>)", "triplet lower by ≈ 9", "≈ 134° (T), ≈ 102° (S)", "the singlet is formed first from CH<sub>2</sub>N<sub>2</sub> photolysis, then decays to the triplet in a dilute gas phase"],
         [":CHCl, :CHBr", "singlet", "singlet lower by a few", "—", "halogen lone pair donates into the empty p"],
         [":CF<sub>2</sub>", "singlet", "singlet lower by ≈ 56", "≈ 105°", "the strongly π-donating, σ-withdrawing F raise the p orbital and lower the σ orbital"],
         [":CCl<sub>2</sub>", "singlet", "singlet lower by ≈ 13", "≈ 109°", "electrophilic carbene, most used in the laboratory"],
         [":CH–OH, :C(OCH<sub>3</sub>)<sub>2</sub>", "singlet", "singlet lower by ≥ 10–25", "—", "O lone pair → empty p orbital"],
         ["(R<sub>2</sub>N)<sub>2</sub>C: (NHC)", "singlet", "singlet lower by ≈ 80", "N–C–N 101–105°", "stable, isolable (Arduengo 1991); nucleophilic"],
         [":CPh<sub>2</sub>", "triplet", "triplet lower by ≈ 3", "≈ 150°", "phenyls delocalise the unpaired electron (benzylic radical-like) and widen the angle; diphenylcarbene is persistent in a rigid matrix (EPR)"],
         ["fluorenylidene", "triplet (≈ degenerate)", "≈ 1", "—", "both states react; photolysis of 9-diazofluorene gives mixtures"],
         [":C=C=C (vinylidene), :C=CH<sub>2</sub>", "singlet", "—", "linear-like", "rearranges to acetylene by 1,2-H shift"],
         ["HC≡C–C–H (propargylene)", "triplet", "—", "bent", "diradical character"]],
        widths=[16, 14, 22, 18, 30])
    B.ul(["<b>Rule.</b> A carbene is singlet when the σ–p gap is large (&gt; 2 eV, ≈ 46 kcal mol<sup>−1</sup>), triplet when it is small (&lt; 1.5 eV). Substituents that <b>raise the p orbital</b> (π-donors: N, O, S, halogens, through donation of a lone pair into the empty p orbital) and those that <b>lower the σ orbital</b> (σ-acceptors/electronegative: F, Cl, OR, NR<sub>2</sub> through −I) both stabilise the singlet. Conjugating, bulky or σ-donating groups (H, alkyl, aryl, silyl) narrow the gap and favour the triplet.",
          "<b>Bond angle follows multiplicity.</b> A smaller angle (≈ 100–110°, more p-character in the σ lone pair, singlet) versus a larger angle (≈ 130–180°, triplet: the linear limit of a carbon with two sp bonds and two p electrons in degenerate p orbitals is a ³Σ<sup>−</sup> triplet).",
          "<b>Physical consequences.</b> Singlet carbenes react in concerted, stereospecific steps (zwitterionic character: lone pair nucleophilic, p orbital electrophilic); triplet carbenes react as diradicals (H-atom abstraction, stepwise additions, loss of stereochemistry). Triplet carbenes are paramagnetic and give EPR signals (zero-field splitting D ≈ 0.4 cm<sup>−1</sup> for CH<sub>2</sub>, 0.4 for Ph<sub>2</sub>C) which is how diphenylcarbene was identified (Wasserman, Hutton, 1962; first triplet organic carbene seen by ESR).",
          "<b>Heavier analogues.</b> Silylenes (SiH<sub>2</sub>: singlet, gap 21 kcal mol<sup>−1</sup>), germylenes, stannylenes and plumbylenes are singlet ground states with ever-growing stability (inert-pair effect); SiCl<sub>2</sub>, SnCl<sub>2</sub>, PbCl<sub>2</sub> are isolable."])
    B.h2("10.8  Generation of carbenes: a complete catalogue")
    B.table(["Method", "Precursor and conditions", "Notes and examples"],
        [["Diazoalkane decomposition", "R<sub>2</sub>C=N<sub>2</sub>, hν, Δ, or metal (Cu, Rh<sub>2</sub>(OAc)<sub>4</sub>, Pd(OAc)<sub>2</sub>)", "CH<sub>2</sub>N<sub>2</sub> (from N-methyl-N-nitrosourea or Diazald + base) → :CH<sub>2</sub> + N<sub>2</sub>; with metals, metal carbenoids (more selective, bear no free CH<sub>2</sub>); explosive and toxic, handle dilute in ether"],
         ["α-Diazoketones", "RCOCHN<sub>2</sub>, Ag<sub>2</sub>O/H<sub>2</sub>O (Arndt–Eistert) or hν", "acylcarbene → Wolff rearrangement to ketene → homologated acid/ester/amide (RCOOH → RCH<sub>2</sub>COOH via RCOCl + CH<sub>2</sub>N<sub>2</sub>)"],
         ["Diazirines", "3H-diazirines (cyclic, 3-membered, C(N=N)); hν (350 nm)", "small, stable photolabile source of carbenes (aryl-CF<sub>3</sub>-diazirine) used in photoaffinity labelling; also isomerises to the linear diazo compound"],
         ["Tosylhydrazone salts", "R<sub>2</sub>C=N–NHTs + NaOMe/Δ (Bamford–Stevens); R<sub>2</sub>C=N–NHTs + 2 RLi (Shapiro)", "aprotic solvent: carbene (then alkene by 1,2-H shift); protic solvent: carbocation by protonation of the diazo compound; Shapiro: vinyl-lithium via α-elimination of sulfinate, no carbene"],
         ["Ketene photolysis", "CH<sub>2</sub>=C=O, hν (λ &lt; 330 nm)", "→ :CH<sub>2</sub> + CO (historic method for ³CH<sub>2</sub> in the gas phase)"],
         ["α-Elimination of haloforms", "CHX<sub>3</sub> + KOH/tBuOK, or PTC (BnEt<sub>3</sub>N<sup>+</sup>Cl<sup>−</sup>, 50 % NaOH)", "CCl<sub>3</sub><sup>−</sup> → :CCl<sub>2</sub> + Cl<sup>−</sup>; CHBr<sub>3</sub> → :CBr<sub>2</sub>; CHI<sub>3</sub> would give :CI<sub>2</sub> but is not used"],
         ["Decarboxylation of trihaloacetate", "Cl<sub>3</sub>CCOONa, 80–90 °C (DME) or ClCF<sub>2</sub>COONa, 180 °C", "Cl<sub>3</sub>C–COO<sup>−</sup> → CCl<sub>3</sub><sup>−</sup> + CO<sub>2</sub> → :CCl<sub>2</sub>; neutral conditions, no HO<sup>−</sup>"],
         ["Organomercurials (Seyferth)", "PhHgCCl<sub>2</sub>Br, PhHgCCl<sub>3</sub>, PhHgCF<sub>3</sub>/NaI, Δ", "neutral, base-free source of :CCl<sub>2</sub>, :CBrCl, :CF<sub>2</sub>; mercury is toxic, rarely used now"],
         ["Reduction of gem-dihalides", "CH<sub>2</sub>I<sub>2</sub> + Zn(Cu) (Simmons–Smith); CH<sub>2</sub>I<sub>2</sub> + Et<sub>2</sub>Zn (Furukawa); CH<sub>2</sub>Cl<sub>2</sub>/BuLi", "carbenoid ICH<sub>2</sub>ZnI (not free :CH<sub>2</sub>); stereospecific syn, directed by allylic OH; ClCH<sub>2</sub>Li at −100 °C"],
         ["Fragmentation of strained rings", "cyclopropenes, oxiranes (deoxygenation), thiiranes, epoxy-ketones", "cyclopropene → vinylcarbene (reversible); photolysis of bicyclic azirines/cyclopropenones: PhC≡CPh via ring opening, giving :C=O"],
         ["Photolysis of ketones/alkenes", "alkenes (Hg-sensitised) → vinylidenes; allene; 1,2-shifts", "H<sub>2</sub>C=C: from acetylene by 1,2-H shift (reverse of the alkyne ⇌ vinylidene rearrangement)"],
         ["Dehydrohalogenation of vinyl halides", "R<sub>2</sub>C=CHX, KOtBu", "1,1-elimination gives vinylidene :C=CR<sub>2</sub>, 1,2-H shift → alkyne (Fritsch–Buttenberg–Wiechell)"],
         ["Metal-bound carbenes", "R<sub>2</sub>C=N<sub>2</sub> + LnM (Rh, Cu, Pd, Ru); Fischer-type (CO)<sub>5</sub>W=C(OMe)Ph", "no free carbene; metal–carbene complex transfers CR<sub>2</sub>; important in catalytic cyclopropanation, C–H functionalisation, olefin metathesis (Grubbs, Schrock)"],
         ["Deprotonation of azolium salts", "imidazolium/thiazolium + base (KOtBu, NaH)", "NHC; thiazolium carbene is the active catalyst of thiamine (vitamin B<sub>1</sub>) and benzoin/Stetter reactions"],
         ["Reaction of alkyl dihalide with base", "CH<sub>2</sub>Cl<sub>2</sub>, NaNH<sub>2</sub> / CH<sub>2</sub>Cl<sub>2</sub>, KOtBu (weak)", ":CHCl; the haloform route is easier than for CH<sub>2</sub>Cl<sub>2</sub> because CCl<sub>3</sub><sup>−</sup> is more stable"]],
        widths=[22, 34, 44])
    B.h2("10.9  Reactions of carbenes: a systematic survey")
    B.h3("(a) Addition to C=C: cyclopropanation, with Skell’s stereochemical test")
    B.ul(["<b>Singlet carbenes add in a single concerted, stereospecific syn step</b> (non-linear approach in which the alkene π electrons enter the empty p orbital while the carbene lone pair attacks the other carbon): cis-2-butene gives cis-1,2-dimethylcyclopropane; trans-2-butene gives only the trans isomer (Skell 1956; Doering).",
          "<b>Triplet carbenes add in two steps</b>: the first bond gives a 1,3-diradical whose spin must flip before ring closure; internal rotation about C–C competes with closing, so both cis- and trans-cyclopropanes arise from either alkene isomer (with a stereospecificity that falls as the pressure of the gas falls and the lifetime of the diradical rises). Photosensitised (benzophenone) photolysis of diazomethane gives ³CH<sub>2</sub>: cis-2-butene → 1:1 cis/trans.",
          "<b>Dichlorocarbene is an electrophile</b>: its addition is faster to electron-rich alkenes. Approximate order of reactivity: Me<sub>2</sub>C=CMe<sub>2</sub> &gt; Me<sub>2</sub>C=CHMe &gt; Me<sub>2</sub>C=CH<sub>2</sub> &gt; cis-RCH=CHR &gt; RCH=CH<sub>2</sub> &gt; CH<sub>2</sub>=CH<sub>2</sub> &gt; electron-poor alkenes (acrylonitrile is almost inert); dichlorocarbene adds to a styrene double bond faster than to a simple alkene. Unsubstituted methylene (¹CH<sub>2</sub>) is far less selective (add to every π bond and insert into every C–H).",
          "<b>Diastereoselectivity.</b> Simmons–Smith cyclopropanation is directed syn to a hydroxyl or ether group on an allylic carbon (the zinc coordinates oxygen); free-carbene additions are controlled by sterics (attack from the less hindered face); bicyclic alkenes (norbornene) give exo products.",
          "<b>Ring expansion by dihalocarbene.</b> Indole + CHCl<sub>3</sub>/NaOEt → 3-chloroquinoline; pyrrole → 3-chloropyridine (Ciamician–Dennstedt rearrangement): the dihalocyclopropane intermediate opens with expulsion of Cl<sup>−</sup>. Cyclic alkenes yield the cyclopropane that can be ring-opened to a ring-expanded cycloalkene (e.g. 7,7-dihalonorcarane + Ag<sup>+</sup> → 2-halocycloheptenyl cation: used to make cycloheptene derivatives)."])
    B.h3("(b) Insertion into σ bonds")
    B.ul(["<b>Singlet CH<sub>2</sub> inserts into C–H bonds indiscriminately</b> (1° : 2° : 3° ≈ 1 : 1.2 : 1.5 per H in solution, recalled): pentane + CH<sub>2</sub>N<sub>2</sub>/hν gives hexane, 2-methylpentane and 3-methylpentane in roughly statistical ratio. The insertion has a three-centre TS; the configuration at the carbon is retained when chiral (insertion at a chiral centre proceeds with retention, in concerted insertion).",
          "<b>Triplet CH<sub>2</sub> reacts by abstraction–recombination</b>: ³CH<sub>2</sub> + R–H → •CH<sub>3</sub> + R• then recombination; thus the products show scrambling and radical by-products (ethane).",
          "<b>X–H insertion</b> (O–H, N–H, S–H, Si–H, Sn–H): ROH + :CH<sub>2</sub> → ROCH<sub>3</sub> via an oxonium ylide (R–O<sup>+</sup>H–CH<sub>2</sub><sup>−</sup>) and a 1,2-proton shift; with metal carbenoids this is the basis of Rh<sub>2</sub>(OAc)<sub>4</sub>-catalysed O–H and N–H insertion (β-lactam synthesis in the penem route, Merck thienamycin synthesis).",
          "<b>Intramolecular C–H insertion</b> by a rhodium carbenoid builds five-membered rings with high selectivity (1,5-insertion preferred; tertiary &gt; secondary &gt; primary C–H; Taber, Doyle). Free carbenes give mixtures; catalysts control site selectivity.",
          "<b>C–C insertion</b> of carbenes is rare. <b>C–halogen insertion</b>: halocarbenes insert into C–X to give gem-dihalides through ylide formation."])
    B.h3("(c) Ylide formation (Doyle–Kirmse, Stevens, carbonyl ylides)")
    B.p("A carbene reacts with a lone pair on O, S, N or halogen to give an onium ylide, which can (i) undergo a proton shift (insertion product), (ii) a [2,3]-sigmatropic rearrangement if an allyl group is on the heteroatom (Doyle–Kirmse: allyl sulfide + diazoacetate/Rh → homoallyl sulfide), (iii) a [1,2]-Stevens shift, (iv) cycloaddition with a dipolarophile if the ylide is a carbonyl ylide (from carbonyl + carbene: [3+2] with alkenes gives tetrahydrofurans), or (v) a Corey–Chaykovsky epoxide when a sulfur ylide is prepared by deprotonation.")
    B.h3("(d) Rearrangements of carbenes")
    B.table(["Process", "Equation", "Comment"],
        [["1,2-Hydride shift", "R–CH<sub>2</sub>–C̈–R′ → RCH=CHR′", "very fast, k ≈ 10<sup>7</sup>–10<sup>10</sup> s<sup>−1</sup>; the reason alkylcarbenes (CH<sub>3</sub>CH:) rarely give intermolecular reactions, and why Bamford–Stevens in aprotic solvent gives alkenes"],
         ["1,2-Alkyl/aryl shift", "R–C̈–C(R′)<sub>3</sub> → alkene", "slower than hydride; neopentylidene gives 2-methyl-2-butene via methyl shift"],
         ["Wolff rearrangement", "RCO–C̈–R′ → R(R′)C=C=O", "acylcarbene → ketene (the migrating R retains configuration); basis of Arndt–Eistert homologation and ring contraction of cyclic α-diazoketones (e.g. 2-diazocyclohexanone → cyclopentanecarboxylic acid)"],
         ["Cyclopropylcarbene → cyclobutene", "ring expansion", "also cyclobutylidene → methylenecyclopropane; used to interconvert strained rings"],
         ["Vinylcarbene ⇌ cyclopropene", "—", "photolysis of cyclopropenes gives vinylcarbenes; vinylcarbene → cyclopropene thermally; used to make furans and indenes"],
         ["Aryl carbene ring expansion", "PhC̈H → cycloheptatetraene (strained cyclic allene)", "phenylcarbene/benzocyclopropene interconversion; trapped by amines (Wentrup)"],
         ["Vinylidene → acetylene", "R<sub>2</sub>C=C: → RC≡CR (1,2-shift)", "Fritsch–Buttenberg–Wiechell"],
         ["Bridgehead/bicyclic carbene fragmentation", "carbene loses N<sub>2</sub> then adds across a nearby π bond", "used to build tricyclic skeletons (Buchner’s ester)"]],
        widths=[22, 34, 44])
    B.h3("(e) Reactions with arenes: Buchner ring expansion")
    B.p("Carbenes add to benzene to give the norcaradiene (bicyclo[4.1.0]hepta-2,4-diene), which opens in a thermally allowed, disrotatory 6π electrocyclic reaction to cycloheptatriene (Buchner 1885: ethyl diazoacetate + benzene, Cu or Rh). Electron-withdrawing substituents at C-7 stabilise the norcaradiene valence tautomer (equilibrium). In intramolecular variants (Buchner–Curtius–Schlotterbeck), α-diazoketones with aryl tethers give azulenones.")
    B.h2("10.10  Carbenoids: the ‘free carbene’ is the exception")
    B.ul(["A <b>carbenoid</b> is a species with carbene-like reactivity but in which the divalent carbon is bound to a metal and leaving group: LiCH<sub>2</sub>Cl, ICH<sub>2</sub>ZnI, [Rh]=CHCO<sub>2</sub>Et, MeCCl<sub>2</sub>Li (Doering–LaFlamme). It transfers CR<sub>2</sub> in a single concerted step (the metal delivers the carbon with its leaving group still partially bound), with selectivity patterns different from the free carbene.",
          "<b>Simmons–Smith</b> (Zn–Cu couple, CH<sub>2</sub>I<sub>2</sub>, ether): I–CH<sub>2</sub>–Zn–I (zinc carbenoid) adds to the alkene through a three-centre ‘butterfly’ TS to give the cyclopropane with retention of alkene geometry. Reaction with electron-rich alkenes is faster; allylic alcohols and ethers direct the addition syn. Furukawa modification: Et<sub>2</sub>Zn replaces Zn(Cu). Charette: enantioselective with chiral dioxaborolane ligands.",
          "<b>Doering–LaFlamme allene synthesis</b>: 1,1-dihalocyclopropane + RLi (or Mg) → carbenoid → cyclopropylidene → ring opening to the allene (via disrotatory electrocyclic opening). Combined with dihalocarbene addition, it converts an alkene R<sub>2</sub>C=CR<sub>2</sub> into an allene R<sub>2</sub>C=C=CR<sub>2</sub> with one more carbon.",
          "<b>Rh<sub>2</sub>(OAc)<sub>4</sub> and Cu(acac)<sub>2</sub>-catalysed decompositions</b> of diazo compounds proceed via a metal carbenoid (M=CR<sub>2</sub>); chiral Rh<sub>2</sub>(S-DOSP)<sub>4</sub> and Cu–bis(oxazoline) give enantioselective cyclopropanations (Davies, Doyle, Pfaltz; Nobel-related work in asymmetric catalysis). The first commercial application was the synthesis of the pyrethroid insecticide chrysanthemic ester (Aratani, Sumitomo).",
          "<b>Fischer carbenes</b> (CO)<sub>5</sub>Cr=C(OMe)R: a low-oxidation-state metal with π-acceptor ligands makes the carbene carbon electrophilic (attack by nucleophiles at C), whereas <b>Schrock carbenes</b> (high-oxidation-state early metals, e.g. Ta(=CHtBu)) are nucleophilic at C. <b>Grubbs/Schrock olefin-metathesis catalysts</b> are metal alkylidenes: [2+2] with an alkene gives a metallacyclobutane which cycloreverts to a new alkene and a new carbene (Chauvin mechanism; Nobel Prize 2005)."])
    B.h2("10.11  Stable carbenes: from curiosity to catalysts")
    B.ul(["<b>Wanzlick</b> (1960s) proposed N-heterocyclic carbenes; <b>Arduengo</b> isolated the first crystalline NHC (1,3-di-adamantylimidazol-2-ylidene, 1991) by deprotonation of the imidazolium chloride with NaH/DMSO. <b>Bertrand</b> reported the first stable acyclic carbene (phosphino-silyl, 1988) and cyclic (alkyl)(amino)carbenes (CAAC).",
          "<b>Why NHCs are stable.</b> (i) Two adjacent nitrogen atoms donate their lone pairs into the empty carbene p orbital (π-donation, aromatic six-π-electron imidazole ring), (ii) the electronegative nitrogens inductively stabilise the σ lone pair, which raises the singlet–triplet gap to ≈ 80 kcal mol<sup>−1</sup>, (iii) bulky N-substituents (adamantyl, 2,6-diisopropylphenyl, mesityl) prevent dimerisation to the tetra-aminoethylene (Wanzlick equilibrium).",
          "<b>Reactivity of NHCs</b>: strongly σ-donating and nucleophilic; excellent ligands for metals (Grubbs II, Pd–PEPPSI), organocatalysts for the benzoin condensation (aryl aldehyde → benzoin), Stetter (aldehyde + Michael acceptor), umpolung of aldehydes; the same pattern as thiamine pyrophosphate (thiazolium ylide) in pyruvate decarboxylase and transketolase.",
          "<b>Link to Part 8:</b> an NHC adds to PhCHO to give the Breslow intermediate (an enaminol), the acyl-anion equivalent. This is the NHC equivalent of the cyanohydrin anion (mechanism 8.9) used for the benzoin condensation: both achieve ‘umpolung’ (polarity inversion) of the carbonyl carbon."])
    B.h2("10.12  Evidence for carbenes and experimental techniques")
    B.ul(["<b>Trapping</b> with alkenes (cyclopropane), with O–H/N–H/Si–H, or with a cheletropic acceptor; the stereochemistry reveals the spin state (Skell test).",
          "<b>Matrix-isolation IR/UV</b> (argon, 10 K) identifies the carbene directly; <b>ESR</b> detects triplets (³CH<sub>2</sub> by Wasserman, Ph<sub>2</sub>C: by Hutton).",
          "<b>Laser flash photolysis</b> gives lifetimes: Ph<sub>2</sub>C: ≈ 1 μs in solution, reacting with methanol (O–H insertion) at ≈ 10<sup>8</sup> M<sup>−1</sup> s<sup>−1</sup> (singlet) and with O<sub>2</sub> at 10<sup>9</sup> (triplet); the product ratio with alcohol versus with O<sub>2</sub>/alkene identifies the state in equilibrium.",
          "<b>Isotope and cross-over experiments</b>: Hine showed that :CCl<sub>2</sub> from CHCl<sub>3</sub>/HO<sup>−</sup> is formed in a reversible deprotonation (H/D exchange of CHCl<sub>3</sub> in D<sub>2</sub>O/OD<sup>−</sup> is faster than hydrolysis) followed by the rate-limiting loss of Cl<sup>−</sup> (so CCl<sub>3</sub><sup>−</sup> is an intermediate; the rate law is first order in HO<sup>−</sup> and in CHCl<sub>3</sub>, retarded by added Cl<sup>−</sup>: common-ion effect, the signature of S<sub>N</sub>1-like rate-determining α-elimination).",
          "<b>Hydrolysis of CHCl<sub>3</sub> by the carbene path</b> gives formate and CO: :CCl<sub>2</sub> + 2 HO<sup>−</sup> → CO + 2 Cl<sup>−</sup> + H<sub>2</sub>O (and, with more hydroxide, HCOO<sup>−</sup>)."])
    B.warn("<b>Typical errors in carbene questions.</b> (1) Calling a carbene ‘electron-deficient with a positive charge’: it is neutral with a sextet. (2) Assuming all carbenes give stereospecific syn addition; only singlets do. (3) Giving a carbocation product under Bamford–Stevens conditions: it depends on the solvent. (4) Forgetting that the Reimer–Tiemann reaction yields mainly the <i>ortho</i> aldehyde (via the phenoxide), and that para is minor. "
           "(5) Writing :CCl<sub>2</sub> inserting into C–H bonds: dichlorocarbene prefers addition to C=C. (6) Using :CH<sub>2</sub> from CH<sub>2</sub>Cl<sub>2</sub>/base in exam questions where Simmons–Smith is meant: CH<sub>2</sub>I<sub>2</sub>/Zn–Cu gives a carbenoid, not free methylene. (7) Mistaking Wolff for a carbocation 1,2-shift: the carbene α to carbonyl rearranges concertedly with loss of N<sub>2</sub>; a tertiary R group migrates with retention.")


def mechanisms(B):
    c = []
    c.append(ex("10.9", "Buchner ring expansion: benzene + :CH<sub>2</sub> → norcaradiene → cycloheptatriene",
        "[CH:1]1=[CH:2][CH:3]=[CH:4][CH:5]=[CH:6]1.[CH2:10]",
        [St([A(('b', 1, 2), ('nb', 1, 10), 0.5), A(('lp', 10), ('nb', 10, 2), -0.5)], "cyclopropanation"),
         St([A(('b', 1, 2), ('nb', 2, 3), 0.5), A(('b', 3, 4), ('nb', 4, 5), 0.5), A(('b', 5, 6), ('nb', 6, 1), 0.5)], "6π disrotatory electrocyclic opening", expect="C1=CC=CCC=C1")],
        "C1=CC=CCC=C1",
        "Methylene adds to one π bond of benzene (cyclopropanation) to give norcaradiene, a cyclohexadiene with a cyclopropane fused at C-1/C-6. The cyclopropane σ bond shared with the six-membered ring and the two double bonds form a 6π electron system (σ + π + π); thermally, a disrotatory electrocyclic ring-opening gives the seven-membered cycloheptatriene (the two valence tautomers interconvert; electron-withdrawing groups at C-7 favour norcaradiene).", width=680))
    c.append(ex("10.10", "Triplet methylene adds stepwise: diradical intermediate, then ring closure after spin flip",
        "[CH2:1].[CH3:6][CH:2]=[CH:3][CH3:7]",
        [St([R(('rad', 1), ('nb', 1, 2), 0.4), R(('b', 2, 3, 3), ('nb', 1, 2), -0.4)], "first bond", rad=True),
         St([R(('rad', 1), ('nb', 1, 3), 0.4), R(('rad', 3), ('nb', 1, 3), -0.4)], "spin flip, then ring closure", rad=True, expect="CC1CC1C")],
        "CC1CC1C",
        "In the triplet the two non-bonding electrons have parallel spin, so the first bond leaves a 1,3-diradical that cannot close until a spin flip (intersystem crossing) converts it into a singlet. During this time (10<sup>−10</sup>–10<sup>−9</sup> s) rotation about the former C=C bond can occur, so cis- and trans-2-butene both give a mixture of cis- and trans-1,2-dimethylcyclopropane: the lack of stereospecificity is the experimental signature of the triplet (Skell).", width=680))
    c.append(ex("10.11", "Diazomethane esterification: no carbene, a protonation / S<sub>N</sub>2 sequence",
        "[CH2-:1][N+:2]#[N:3].[H:10][O:11][C:12](=[O:13])[CH3:14]",
        [St([A(('lp', 1), ('nb', 1, 10), 0.5), A(('b', 10, 11), ('lp', 11), 0.5)], "proton transfer", expect="C[N+]#N.CC(=O)[O-]"),
         St([A(('lp', 11), ('nb', 11, 1), 0.5), A(('b', 1, 2), ('lp', 2), 0.5)], "S_N2, −N_2", expect="COC(C)=O.N#N")],
        "COC(C)=O.N#N",
        "The nucleophilic carbon of CH<sub>2</sub>N<sub>2</sub> is protonated by the acid (pK<sub>a</sub> ≲ 10 needed), giving the methyldiazonium ion – an extremely good alkylating agent (leaving group N<sub>2</sub>) – which is attacked by the carboxylate in an S<sub>N</sub>2 step. Diazomethane therefore methylates carboxylic acids and phenols quantitatively under mild conditions, though no free CH<sub>2</sub> appears; it is the same compound that gives :CH<sub>2</sub> on photolysis.", width=680))
    c.append(ex("10.12", "Doering–LaFlamme: cyclopropylidene → allene (disrotatory electrocyclic ring opening)",
        "[C:1]1[CH2:2][CH2:3]1",
        [St([A(('lp', 1), ('nb', 1, 2), 0.5), A(('b', 2, 3), ('nb', 1, 3), -0.5)], "ring opening", expect="C=C=C")],
        "C=C=C",
        "The cyclopropylidene (formed from a 1,1-dihalocyclopropane and BuLi or Mg through the α-halo-lithium carbenoid) opens by breaking the distal C–C bond of the ring. The carbene lone pair and the σ electrons of the C2–C3 bond are converted into the two C=C π bonds of the allene: the process is a two-electron ring-opening that releases the cyclopropane strain (27 kcal mol<sup>−1</sup>) and converts a carbene into a stable cumulene. Together with the addition of :CBr<sub>2</sub> to an alkene, it converts C=C into C=C=C with one additional carbon.", width=680))
    B.grid(c, 2)


def problems(B, q):
    q(13, "Predict the products and the stereochemistry: (a) cis-2-butene + CH<sub>2</sub>N<sub>2</sub>/hν (direct photolysis, dilute in liquid), (b) cis-2-butene + CH<sub>2</sub>N<sub>2</sub>/hν/benzophenone, (c) trans-2-butene + CHCl<sub>3</sub>/KOtBu.",
      S([("a", "CC1CC1C"), ("b", "CC1CC1C"), ("c", "CC1C(C)C1(Cl)Cl")]),
      "(a) cis-1,2-dimethylcyclopropane only (plus C–H insertion products); (b) mixture of cis and trans; (c) trans-1,1-dichloro-2,3-dimethylcyclopropane (stereospecific)",
      "(a) singlet CH<sub>2</sub> (direct photolysis): one-step, stereospecific syn addition. (b) triplet sensitisation: stepwise diradical, scrambling of stereochemistry. (c) :CCl<sub>2</sub> is a singlet; the trans-alkene stereochemistry is preserved.")
    q(14, "How many monobromo/mono-methylated insertion products (C<sub>n+1</sub> alkanes) are formed when singlet methylene reacts with propane? Estimate the ratio assuming statistical insertion (1° : 2° = 1 : 1.2 per H).",
      S([("n-butane", "CCCC"), ("isobutane", "CC(C)C")]), "2 products: n-butane : isobutane = 6 : 2.4 = 71 : 29 (statistical would be 75 : 25)",
      "Insertion into a 1° C–H (6 H) gives n-butane; into the 2° C–H (2 H) gives isobutane (2-methylpropane). Weights 6 × 1 = 6 and 2 × 1.2 = 2.4.")
    q(15, "Account for the fact that CHCl<sub>3</sub> + OD<sup>−</sup> in D<sub>2</sub>O exchanges H for D faster than it hydrolyses, and that the hydrolysis is retarded by added Cl<sup>−</sup>.",
      None, "reversible carbanion formation followed by rate-limiting loss of Cl<sup>−</sup>", "CHCl<sub>3</sub> + HO<sup>−</sup> ⇌ CCl<sub>3</sub><sup>−</sup> + H<sub>2</sub>O (fast, reversible: D exchange); CCl<sub>3</sub><sup>−</sup> → :CCl<sub>2</sub> + Cl<sup>−</sup> (slow); :CCl<sub>2</sub> + H<sub>2</sub>O/HO<sup>−</sup> → CO + HCOO<sup>−</sup>. Added chloride pushes the second step backwards (common-ion effect), exactly as in an S<sub>N</sub>1 reaction (Hine, 1950s).")
    q(16, "Arrange in decreasing order of stability of the singlet over the triplet: :CH<sub>2</sub>, :CHF, :CF<sub>2</sub>, :C(OCH<sub>3</sub>)<sub>2</sub>, :CPh<sub>2</sub>.",
      None, ":CF<sub>2</sub> ≈ :C(OCH<sub>3</sub>)<sub>2</sub> &gt; :CHF &gt; :CH<sub>2</sub> (triplet ground) &gt; :CPh<sub>2</sub> (triplet ground, widest angle)", "π-donation from lone pairs on F and O into the empty p orbital plus inductive stabilisation of the σ orbital favour the singlet; two such substituents act cumulatively. H and alkyl do not; conjugating phenyls favour the triplet.")
    q(17, "An unknown carbene gives 100 % cis-cyclopropane from cis-2-butene in solution but a 1:1 cis/trans mixture in the gas phase at low pressure. Interpret.",
      None, "singlet carbene that relaxes (intersystem crossing) to the triplet before reacting", "In solution, collisions with solvent quickly deactivate the energy but the singlet reacts at once: stereospecific. At low pressure the initially formed singlet has a long time before reacting and collisions induce ISC to the triplet ground state, giving the stepwise, non-stereospecific path (Skell/Bader). The cross-over from stereospecific to non-stereospecific with dilution shows that the singlet is the initial state.")
    q(18, "Phenol is heated with chloroform and NaOH. (a) Name the main product, (b) say why para isomer is minor, (c) identify the electrophile and write the intermediate before hydrolysis.",
      S([("main", "O=Cc1ccccc1O"), ("minor", "O=Cc1ccc(O)cc1")]), "(a) salicylaldehyde (2-hydroxybenzaldehyde); (b) ion-pair / coordination of Na<sup>+</sup> with the phenoxide and carbene directs ortho; (c) :CCl<sub>2</sub>; the intermediate is the dichloromethyl cyclohexadienone which loses Cl<sup>−</sup> to give the o-quinone methide-type chloride that is hydrolysed",
      "Phenoxide is a strong activator; dichlorocarbene (electrophile) attacks the ortho (and para) carbon; Na<sup>+</sup> coordination of the oxygen and the incoming carbene favour ortho (ortho : para ≈ 3 : 1). Hydrolysis of the ArCHCl<sub>2</sub> (aryl-CHCl<sub>2</sub> with phenoxide → o-quinone methide → ArCHO) gives the aldehyde. With CCl<sub>4</sub> the product is the carboxylic acid (salicylic acid) and with CHBr<sub>3</sub> the same aldehyde.")
    q(19, "Give the products: (a) PhCOCl + CH<sub>2</sub>N<sub>2</sub> (excess), then Ag<sub>2</sub>O/H<sub>2</sub>O/Δ; (b) the same with C<sub>2</sub>H<sub>5</sub>OH in place of water; (c) 2-diazocyclohexanone, hν, H<sub>2</sub>O.",
      S([("a", "OC(=O)Cc1ccccc1"), ("b", "CCOC(=O)Cc1ccccc1"), ("c", "OC(=O)C1CCCC1")]), "(a) phenylacetic acid; (b) ethyl phenylacetate; (c) cyclopentanecarboxylic acid", "Arndt–Eistert: acid chloride + CH<sub>2</sub>N<sub>2</sub> → diazoketone (second equivalent removes HCl as CH<sub>3</sub>Cl); Ag<sup>+</sup> catalyses Wolff rearrangement to a ketene PhCH=C=O; water or ethanol adds. In (c) the Wolff rearrangement contracts the ring by one carbon.")
    q(20, "Explain why diazomethane methylates RCOOH and phenols (ArOH) but not alcohols (ROH) in the absence of a catalyst (BF<sub>3</sub> or HBF<sub>4</sub>).",
      None, "pK<sub>a</sub> threshold for protonating CH<sub>2</sub>N<sub>2</sub>", "The first step is proton transfer to carbon. The conjugate acid CH<sub>3</sub>N<sub>2</sub><sup>+</sup> is a very strong acid; CH<sub>2</sub>N<sub>2</sub> is protonated significantly only by acids with pK<sub>a</sub> ≲ 10 (carboxylic acids, phenols, enols, 1,3-dicarbonyls); alcohols (≈ 16) are too weak. A Lewis-acid catalyst makes the alcohol react.")
    q(21, "Which of the following gives a free carbene? (a) CH<sub>2</sub>I<sub>2</sub> + Zn(Cu); (b) CH<sub>2</sub>N<sub>2</sub> + hν; (c) CHCl<sub>3</sub> + tBuOK; (d) Ph<sub>2</sub>C=N<sub>2</sub> + Δ; (e) CH<sub>2</sub>I<sub>2</sub> + Et<sub>2</sub>Zn; (f) CH<sub>2</sub>N<sub>2</sub> + CH<sub>3</sub>COOH.",
      None, "(b), (c), (d)", "(a) and (e) give the zinc carbenoid ICH<sub>2</sub>ZnI; (f) is protonation of CH<sub>2</sub>N<sub>2</sub> and S<sub>N</sub>2 (ester formation). The others lose N<sub>2</sub> or Cl<sup>−</sup> to produce :CH<sub>2</sub>, :CCl<sub>2</sub> and Ph<sub>2</sub>C: respectively.")
    q(22, "How many different constitutional isomers of C<sub>7</sub>H<sub>16</sub> can be formed by insertion of singlet :CH<sub>2</sub> into the C–H bonds of 2-methylpentane?",
      None, "5", "2-Methylpentane (CH<sub>3</sub>)<sub>2</sub>CH–CH<sub>2</sub>–CH<sub>2</sub>–CH<sub>3</sub> has five sets of non-equivalent hydrogens (C-1/C-1′, C-2, C-3, C-4, C-5). Insertion into each gives a different heptane: C-1–H → 3-methylhexane; C-2–H → 2,2-dimethylpentane; C-3–H → 2,3-dimethylpentane; C-4–H → 2,4-dimethylpentane; C-5–H → 2-methylhexane. All five are different constitutional isomers.")
    q(23, "A student states that all carbenes are intermediates that add to alkenes with retention of alkene stereochemistry. Give two counterexamples.",
      None, "triplet carbenes; carbenoids of different type", "(1) ³CH<sub>2</sub> and Ph<sub>2</sub>C: (triplet) add stepwise and scramble stereochemistry. (2) Metal carbenes (Fischer type) undergo [2+2]/metathesis rather than cyclopropanation. Also singlet carbenes with electron-poor alkenes can give nucleophilic ylide-type additions.")
    q(24, "What is the product when bicyclo[4.1.0]heptane-7,7-dichloride (7,7-dichloronorcarane) is treated with methyllithium?",
      S([("", "ClC1(Cl)C2CCCCC12"), ("→", "C1CCC=C=CC1")]), "1,2-cycloheptadiene (strained cyclic allene, via the carbenoid and the cyclopropylidene), trapped as a dimer or cycloadduct", "Li/Cl exchange gives the carbenoid, loss of LiCl gives the bicyclic cyclopropylidene, which opens (Doering–LaFlamme) to the strained cyclic allene (1,2-cycloheptadiene) – isolable only as dimer or Diels–Alder adduct; with a more substituted ring the allene is isolable (eight-membered or larger).")
    q(25, "Write a balanced equation for the complete alkaline hydrolysis of dichlorocarbene by hydroxide, and state the carbon-containing product.",
      None, ":CCl<sub>2</sub> + 2 HO<sup>−</sup> → CO + 2 Cl<sup>−</sup> + H<sub>2</sub>O  (and HCOO<sup>−</sup> with more hydroxide)", "Hydroxide attacks the carbene carbon; loss of chloride and a proton shift give HO–C̈–Cl-type species that lose HCl to carbon monoxide. Under strongly basic conditions CO is further hydrated to formate (CO + HO<sup>−</sup> → HCOO<sup>−</sup>). The formation of CO and formate in the hydrolysis of chloroform was part of the evidence for :CCl<sub>2</sub> (Hine).")
    q(26, "Dichlorocarbene is added to buta-1,3-diene. How many constitutional isomers form from one equivalent of carbene? How many stereoisomers are possible when two equivalents add to give the bis-cyclopropane?",
      None, "1 constitutional isomer (1,1-dichloro-2-vinylcyclopropane, as a racemate); the bis-adduct has 3 stereoisomers (R,R; S,S; meso)", "Carbenes add 1,2 to a conjugated diene (no 1,4-addition). Both double bonds of butadiene are equivalent, so one monoadduct forms. In the bis-adduct 2,2,2′,2′-tetrachloro-bicyclopropyl the two ring carbons attached to each other are stereocentres: (R,R), (S,S) and the meso (R,S) form.")
    q(27, "What are the intermediate and the final product of heating the sodium salt of trichloroacetic acid in the presence of cyclohexene?",
      S([("", "ClC1(Cl)C2CCCCC12")]), "CCl<sub>3</sub><sup>−</sup> → :CCl<sub>2</sub>; 7,7-dichloronorcarane", "Decarboxylation of Cl<sub>3</sub>CCOO<sup>−</sup> gives the trichloromethyl carbanion without needing HO<sup>−</sup>, so a base-sensitive alkene or ester can be cyclopropanated under neutral conditions (Wagner, 1954).")
    q(28, "Compare the stability and the reaction type of a carbene, a carbocation, a carbanion and a radical in a table (valence electrons on carbon, charge, geometry, typical role).",
      None, "see table", "CH<sub>3</sub><sup>+</sup>: 6 e, + charge, planar sp<sup>2</sup>, electrophile; CH<sub>3</sub>•: 7 e, neutral, planar-shallow pyramid, radical; CH<sub>3</sub><sup>−</sup>: 8 e, − charge, pyramidal sp<sup>3</sup>, nucleophile/base; :CH<sub>2</sub>: 6 e, neutral, bent (singlet 102°, triplet 134°), ambiphilic (singlet) or diradical (triplet). Full comparison in Part 14.")
    q(29, "How does the Bamford–Stevens reaction of a ketone tosylhydrazone differ from the Shapiro reaction, and how do the products differ for 2-methylcyclohexanone tosylhydrazone?",
      S([("BS", "CC1=CCCCC1"), ("Shapiro", "C=C1CCCCC1".replace("C=C1CCCCC1", "C1=CCCCC1C"))]), "Bamford–Stevens (NaOMe, Δ): more substituted alkene (carbene, 1,2-H shift, thermodynamic: 1-methylcyclohexene); Shapiro (2 RLi): less substituted alkene (3-methylcyclohexene) via the less hindered vinyl-lithium", "In the BS reaction a diazo compound/carbene (or carbocation in protic solvent) leads to the thermodynamic Zaitsev-type alkene; in the Shapiro reaction the dianion removes the more accessible, α′ proton syn to the N–Ts group and extrudes sulfinate and N<sub>2</sub> to give the vinyllithium (no carbene), which is protonated to the kinetic, less substituted alkene.")
    q(30, "(Assertion–Reason) Assertion: dichlorocarbene reacts with propene faster than with acrylonitrile. Reason: dichlorocarbene is an electrophile. Choose.",
      None, "both true; the reason explains the assertion", ":CCl<sub>2</sub> has a vacant p orbital and attacks the electron-rich π bond; the CN group withdraws electron density from CH<sub>2</sub>=CH–CN, so the reaction is slow.")
    q(31, "A chiral ketone R(R′)CH–CO–CHN<sub>2</sub> with R and R′ different is subjected to the Wolff rearrangement. What is the configuration of the migrating carbon in the product acid R(R′)CH–CH<sub>2</sub>COOH?",
      None, "retention", "The migrating group moves from the carbonyl carbon to the carbene carbon with its pair of electrons while retaining configuration, as in all 1,2-shifts to an electron-deficient centre with a concerted three-centre TS (Part 7).")
    q(32, "Predict the product of the intramolecular reaction of 1-diazo-5-phenylpentan-2-one with Rh<sub>2</sub>(OAc)<sub>4</sub> (Buchner) and name the ring formed.",
      None, "a bicyclic azulenone (5–7 fused) via carbene attack on the phenyl ring", "The rhodium carbenoid adds to the arene ring in an intramolecular manner (Buchner reaction) forming the norcaradiene which opens to the cycloheptatriene fused to a cyclopentanone: bicyclo[5.3.0]decatrienone (the azulenone skeleton).")
    q(33, "Why does CH<sub>2</sub>Cl<sub>2</sub> with KOtBu give less carbene than CHCl<sub>3</sub>?",
      None, "CHCl<sub>2</sub><sup>−</sup> is a less stable carbanion than CCl<sub>3</sub><sup>−</sup>", "The acidity of the substrate depends on the number of chlorines (pK<sub>a</sub> ≈ 24 for CHCl<sub>3</sub>, ≈ 32 for CH<sub>2</sub>Cl<sub>2</sub>), and the loss of Cl<sup>−</sup> from CHCl<sub>2</sub><sup>−</sup> gives the more reactive, less stable :CHCl.")
    q(34, "What is the major difference in the products obtained from 1-hexene by (a) CH<sub>2</sub>N<sub>2</sub>/Cu<sub>2</sub>Cl<sub>2</sub> and (b) CH<sub>2</sub>N<sub>2</sub>/hν?",
      None, "(a) butylcyclopropane (selective, carbenoid); (b) butylcyclopropane plus C–H insertion products (isomeric heptenes and alkanes)", "The copper carbenoid is selective for the C=C bond; free ¹CH<sub>2</sub> from photolysis reacts with every C–H bond and gives a mixture.")
    q(35, "Methylene generated from the photolysis of ketene (CH<sub>2</sub>=C=O) in the gas phase reacts with a large excess of N<sub>2</sub> (inert gas) at high pressure. Which spin state reacts and why?",
      None, "triplet", "Collisions with the inert gas relax ¹CH<sub>2</sub> (ISC) to the triplet ground state (≈ 9 kcal below) before reaction. The cis-2-butene products become a mixture of cis and trans dimethylcyclopropanes as the pressure rises (Frey).")
    q(36, "Write the product of treating trans-stilbene with CHBr<sub>3</sub>/50 % NaOH/PTC and then hot with Ag<sup>+</sup>. Name the types of reaction.",
      S([("", "BrC1(Br)C(c2ccccc2)C1c1ccccc1")]), "1,1-dibromo-trans-2,3-diphenylcyclopropane; Ag<sup>+</sup> ionises it to a cyclopropyl cation that ring-opens (disrotatory) to a substituted allyl cation (→ 2-bromo-1,3-diphenylallyl derivatives)", "Cyclopropanation by :CBr<sub>2</sub> followed by silver-assisted electrocyclic ring-opening (Woodward–Hoffmann disrotatory) of the cyclopropyl cation: a stereospecific route to allylic bromides.")
    q(37, "Rank the following by relative rate of addition of :CCl<sub>2</sub> (fastest first): ethylene, 2-methyl-2-butene, 1-hexene, tetramethylethylene, cis-2-butene.",
      None, "tetramethylethylene &gt; 2-methyl-2-butene &gt; cis-2-butene &gt; 1-hexene &gt; ethylene", "The electrophilic carbene reacts faster with more highly alkyl-substituted, electron-rich C=C bonds (hyperconjugative donation): the relative rate roughly tracks the number of alkyl groups (≈ 1 : 10 : 10<sup>2</sup>… in the Doering series).")
